// Offline ROM hash database — CRC32 checksums of the bundled homebrew set.
// Format matches the libretro/OpenVGDB-style (crc32 -> title). Custom games
// scanned from disk are matched here first, then against the user's own
// SQLite library. Fully offline; online scrapers remain optional.
// The builtin table is AUTO-GENERATED by scripts/gen-romdb.mjs. A much larger
// database can be generated with scripts/build-romdb.mjs (OpenVGDB CSV →
// public/romdb.json) and is loaded on demand below.

export interface RomDbEntry {
  crc32: number
  title: string
  platform: string
  year?: number
  author?: string
}

export const ROM_DB: RomDbEntry[] = [
  { crc32: 0x9d307e90, title: 'BLINKY', platform: 'CHIP-8' },
  { crc32: 0xd106c808, title: 'BLITZ', platform: 'CHIP-8' },
  { crc32: 0xaaa44d0b, title: 'BRIX', platform: 'CHIP-8' },
  { crc32: 0x9858889b, title: 'CONNECT4', platform: 'CHIP-8' },
  { crc32: 0x61861ae5, title: 'HIDDEN', platform: 'CHIP-8' },
  { crc32: 0x6e485c29, title: 'MISSILE', platform: 'CHIP-8' },
  { crc32: 0x6ff0a017, title: 'SPACEINVADERS', platform: 'CHIP-8' },
  { crc32: 0x67e4bf9c, title: 'SYZYGY', platform: 'CHIP-8' },
  { crc32: 0xa929cb73, title: 'TANK', platform: 'CHIP-8' },
  { crc32: 0x0ce70772, title: 'TETRIS', platform: 'CHIP-8' },
  { crc32: 0xe5b40a11, title: 'TRON', platform: 'CHIP-8' },
  { crc32: 0x331413e7, title: 'UFO', platform: 'CHIP-8' },
]

// ---------- extended database (optional, generated from OpenVGDB) ----------

interface BigDb {
  [crcHex: string]: [title: string, platform: string, year?: number, author?: string]
}

let bigDb: BigDb | null = null
let bigDbLoading: Promise<void> | null = null

/** Lazily load public/romdb.json when present (generated via build-romdb). */
export function ensureBigDb(): Promise<void> {
  if (bigDb || bigDbLoading) return bigDbLoading ?? Promise.resolve()
  bigDbLoading = (async () => {
    try {
      const res = await fetch(`${import.meta.env.BASE_URL}romdb.json`, { cache: 'force-cache' })
      if (res.ok) bigDb = (await res.json()) as BigDb
    } catch {
      /* not bundled — builtin table only */
    }
  })()
  return bigDbLoading
}

/** Offline CRC32 lookup — builtin table + optional extended OpenVGDB data. */
export function matchRom(crc32: number): RomDbEntry | null {
  const hex = crc32.toString(16)
  if (bigDb) {
    const hit = bigDb[hex]
    if (hit) {
      return { crc32, title: hit[0], platform: hit[1], year: hit[2], author: hit[3] }
    }
  }
  return ROM_DB.find((e) => e.crc32 === crc32) ?? null
}

export function bigDbSize(): number {
  return bigDb ? Object.keys(bigDb).length : 0
}
